    }

    @Override
    public <T> T invokeAny(Collection<? extends Callable<T>> tasks) throws InterruptedException, ExecutionException {
        var state = startInvokeAny(tasks);
        return finishInvokeAny(state, state.completionEither().get());
    }

    /**
     * Submits all tasks, wiring the first successful completion and the all-done signal into a single
     * {@code completionEither} future. The caller awaits {@code completionEither} (optionally with a
     * timeout) and hands the winner back to {@link #finishInvokeAny}.
     */
    private <T> InvokeAnyState<T> startInvokeAny(Collection<? extends Callable<T>> tasks) {
        if (tasks.isEmpty()) {
            throw new IllegalArgumentException("The tasks parameter should contain at least one callable!");
        }

        var completionAll = new CompletableFuture<Void>();
        var signaller = new CompletionSignaller(completionAll);
        var completionPort = new CompletableFuture<CompletedIndexValue<T>>();

        var result = new ArrayList<Future<T>>();
        var i = 0;
        for (var task : tasks) {
            signaller.countUp();
            var j = i;
            result.add(submit(() -> {
                try {
                    var v = task.call();
                    completionPort.complete(new CompletedIndexValue<>(j, v));
                    return v;
                } finally {
                    signaller.countDown();
                }
            }));
            i++;
        }

        signaller.countDown();

        var completionEither = new CompletableFuture<CompletableFuture<?>>();

        completionPort.whenComplete((_, _) -> completionEither.complete(completionPort));
        completionAll.whenComplete((_, _) -> completionEither.complete(completionAll));

        return new InvokeAnyState<>(completionEither, completionPort, result);
    }

    /**
     * Given the awaited winner of {@link #startInvokeAny}, returns the first successful value (cancelling
     * the rest) or throws an {@link ExecutionException} aggregating all failures.
     */
    private <T> T finishInvokeAny(InvokeAnyState<T> state, CompletableFuture<?> resultCompletable)
            throws InterruptedException, ExecutionException {
        if (resultCompletable == state.completionPort()) {
            var k = state.completionPort().getNow(null);
            for (int j = 0; j < state.result().size(); j++) {
                if (j != k.index()) {
                    state.result().get(j).cancel(true);
                }
            }
            return k.value();
        }

        List<Throwable> errors = new ArrayList<>();
        for (var f : state.result()) {
            errors.add(getException(f));
        }
        throw new ExecutionException(new CompositeException(errors));
    }

    private record InvokeAnyState<T>(
            CompletableFuture<CompletableFuture<?>> completionEither,
            CompletableFuture<CompletedIndexValue<T>> completionPort,
            List<Future<T>> result) {
    }

    record CompletedIndexValue<T>(int index, T value) {
    }

    static final class CompletionSignaller extends AtomicInteger {
        @Serial
        private static final long serialVersionUID = 4179219399191354619L;

        final CompletableFuture<Void> signal;

        CompletionSignaller(CompletableFuture<Void> signal) {
            super(1);
            this.signal = signal;
        }

        void countUp() {
            incrementAndGet();
        }

        void countDown() {
            if (decrementAndGet() == 0) {
                signal.complete(null);
            }
        }
    }

    @Override
    public <T> T invokeAny(Collection<? extends Callable<T>> tasks, long timeout, TimeUnit unit)
            throws InterruptedException, ExecutionException, TimeoutException {
        if (tasks.isEmpty()) {
            throw new IllegalArgumentException("The tasks parameter should contain at least one callable!");
        }

        var completionAll = new CompletableFuture<Void>();
        var signaller = new CompletionSignaller(completionAll);
        var completionPort = new CompletableFuture<CompletedIndexValue<T>>();

        var result = new ArrayList<Future<T>>();
        var i = 0;
        for (var task : tasks) {
            signaller.countUp();
            var j = i;
            result.add(submit(() -> {
                try {
                    var v = task.call();
                    completionPort.complete(new CompletedIndexValue<>(j, v));
                    return v;
                } finally {
                    signaller.countDown();
                }
            }));
            i++;
        }

        signaller.countDown();

        var completionEither = new CompletableFuture<CompletableFuture<?>>();

        completionPort.whenComplete((_, _) -> completionEither.complete(completionPort));
        completionAll.whenComplete((_, _) -> completionEither.complete(completionAll));

        var resultCompletable = completionEither.get(timeout, unit);

        if (resultCompletable == completionPort) {
            var k = completionPort.getNow(null);
            for (int j = 0; j < result.size(); j++) {
                if (j != k.index()) {
                    result.get(j).cancel(true);
                }
            }
            return k.value();
        }

        List<Throwable> errors = new ArrayList<>();
        for (var f : result) {
            errors.add(getException(f));
        }
        var composite = new CompositeException(errors);
        throw new ExecutionException(composite);
    }

    static Throwable getException(Future<?> f) throws InterruptedException {
        try {
            f.get();
        } catch (ExecutionException ex) {
            return ex.getCause();
        }
        return null;
    }
}
